def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    rows = []
    current_row = []
    i = 0
    n = len(text)

    while i < n:
        # Satır sonu kontrolü (en sonda değilse yeni satır başlatmak için kullanılır)
        # Ancak metnin sonundaki \n veya \r\n boş kayıt oluşturmamalı.

        field = ""
        if text[i] == '"':
            # Tırnaklı alan başlangıcı
            i += 1  # Başlangıç tırnağını atla
            in_quotes = True
            while i < n:
                if in_quotes:
                    if text[i] == '"':
                        if i + 1 < n and text[i+1] == '"':
                            # Çift tırnak "" -> tek tırnak olarak ekle
                            field += '"'
                            i += 2
                        else:
                            # Tırnak kapandı
                            in_quotes = False
                            i += 1
                            break
                    else:
                        field += text[i]
                        i += 1
                else:
                    # Bu kısım aslında döngü dışında yönetilmeli ama mantığı kuruyoruz
                    pass

            if in_quotes:
                raise ValueError("Kapanmayan tırnak hatası.")

            # Tırnak kapandıktan sonra hemen ayırıcı veya satır sonu gelmeli
            if i < n and text[i] not in (delimiter, '\n', '\r'):
                raise ValueError(f"Hatalı karakter: '{text[i]}' tırnaktan hemen sonra gelemez.")
        else:
            # Tırnaksız alan başlangıcı
            start_idx = i
            while i < n and text[i] not in (delimiter, '\n', '\r'):
                if text[i] == '"':
                    # Tırnaksız alanın ortasında tırnak varsa bu sıradan karakterdir
                    pass 
                i += 1
            field = text[start_idx:i]

        current_row.append(field)

        # Döngüden sonra i'nin ne olduğuna bak (ayırıcı mı, satır sonu mu?)
        if i < n and text[i] == delimiter:
            i += 1
            # Eğer ayırıcı satırın en sonundaysa ve metin bitiyorsa bu durum özeldir ama standart CSV'de boş alan demektir.
            # Ancak kural "metnin sonundaki tek satır sonu yeni kayıt oluşturmaz" diyor.
        elif i < n and (text[i] == '\n' or text[i] == '\r'):
            # Satır sonu bulundu
            rows.append(current_row)
            current_row = []
            if text[i] == '\r' and i + 1 < n and text[i+1] == '\n':
                i += 1 # \r\n için ikisini de atla
            i += 1
            # Eğer metin biterse ve son karakter satır sonuysa, boş kayıt ekleme (kural gereği)
            if i >= n:
                break
        else:
            # Satır sonu veya ayırıcı yoksa ama döngü bittiyse (metin bitişi)
            if i == n and current_row:
                 rows.append(current_row)

    # Metnin sonundaki \n/ \r\n durumunu yönetmek için: 
    # Eğer metin bir satır sonu ile bittiyse ve en son eklenen şey boş bir row değilse, 
    # zaten döngü içinde append yapılmış olabilir. 
    # Ancak kural "Metnin sonundaki tek satır sonu yeni bir kayıt oluşturmaz" diyor.
    # Mevcut mantıkta i >= n olduğunda loop biter. Eğer en son bir delimiter ile bitmişse 
    # ve döngüden çıkıldıysa, current_row boş kalmış olabilir.

    # Basitleştirilmiş ve daha sağlam bir yaklaşım için state machine kullanalım:
    return _parse_logic(text, delimiter)

def _parse_logic(text: str, delimiter: str) -> list[list[str]]:
    if not text:
        return []

    rows = []
    current_row = []
    i = 0
    n = len(text)

    while i < n:
        # Alan (Field) okuma
        field = ""
        if text[i] == '"':
            i += 1 # Başlangıç tırnağı
            in_quotes = True
            while i < n and in_quotes:
                if text[i] == '"':
                    if i + 1 < n and text[i+1] == '"':
                        field += '"'
                        i += 2
                    else:
                        in_quotes = False
                        i += 1
                else:
                    field += text[i]
                    i += 1
            if in_quotes:
                raise ValueError("Kapanmayan tırnak.")

            # Tırnaktan hemen sonra kontrol
            if i < n and text[i] not in (delimiter, '\n', '\r'):
                raise ValueError(f"Hatalı karakter '{text[i]}' tırnaktan hemen sonra gelemez.")
        else:
            start = i
            while i < n and text[i] not in (delimiter, '\n', '\r'):
                i += 1
            field = text[start:i]

        current_row.append(field)

        # Satır sonu veya ayırıcı kontrolü
        if i < n and text[i] == delimiter:
            i += 1
            # Eğer satırın en sonundaysa ve metin bitiyorsa (örn: "a,b,"), bu bir boş alan demektir.
            # Ama kural metnin sonundaki \n için geçerli.
        elif i < n and (text[i] == '\n' or text[i] == '\r'):
            rows.append(current_row)
            current_row = []
            if text[i] == '\r' and i + 1 < n and text[i+1] == '\n':
                i += 1
            i += 1
        elif i >= n:
            # Metin bitti, son satırı ekle (eğer metin boş değilse ve son karakter \n değilse)
            # Kural: "Metnin sonundaki tek satır sonu yeni bir kayıt oluşturmaz"
            # Eğer en son okunan şey bir delimiter ise veya metin zaten bitmişse...
            # Aslında döngü bittiğinde current_row doluysa eklemeliyiz.
            if current_row:
                rows.append(current_row)
        else:
            # Beklenmedik durum (normalde yukarıdakiler kapsar)
            pass

    return rows

# Asıl fonksiyonu _parse_logic ile değiştiriyoruz
def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []
    return _parse_logic(text, delimiter)

